'use strict';

// Seeds the Kalender Islam dataset (data/falak-abi-calendar.json) into the
// single calendar-entry content type: awal-bulan-Hijriah rows plus
// hari-besar/astronomi event rows.
//
// The JSON is generated by the mobile-app repo:
//   ensiklopedia-doa/scripts/falak-abi/generate.js  ->  cms-export.json
// Copy that file here as data/falak-abi-calendar.json when coverage extends.
//
// Idempotent: existing rows (same date+type for month starts, same
// date+title for events) are skipped, so re-running after adding a new year
// only inserts the new rows. Month starts are inserted in date order so the
// continuity lifecycle validation always sees the preceding month.
//
// Run with: npm run import:calendar   (uses the same DATABASE_* env as the
// server, so run it locally for the dev DB or with production env vars for
// the deployed CMS.)

const data = require('../data/falak-abi-calendar.json');

const UID = 'api::calendar-entry.calendar-entry';

const HIJRI_MONTH_NAMES = [
  'Muharam',
  'Safar',
  'Rabiulawal',
  'Rabiulakhir',
  'Jumadilawal',
  'Jumadilakhir',
  'Rajab',
  'Syakban',
  'Ramadan',
  'Syawal',
  'Zulqaidah',
  'Zulhijah',
];

async function importMonthStarts(app) {
  let created = 0;
  let skipped = 0;
  const sorted = [...data.monthStarts].sort((a, b) => a.g.localeCompare(b.g));
  for (const start of sorted) {
    const existing = await app.documents(UID).findFirst({
      filters: { date: start.g, type: 'awal_bulan_hijriah' },
    });
    if (existing) {
      skipped++;
      continue;
    }
    await app.documents(UID).create({
      data: {
        date: start.g,
        type: 'awal_bulan_hijriah',
        hijriMonth: HIJRI_MONTH_NAMES[start.hm],
        hijriYear: start.hy,
      },
    });
    created++;
  }
  console.log(`Month starts: ${created} created, ${skipped} skipped (already present)`);
}

async function importEvents(app) {
  let created = 0;
  let skipped = 0;
  for (const event of data.events) {
    const existing = await app.documents(UID).findFirst({
      filters: { date: event.date, title: event.text },
    });
    if (existing) {
      skipped++;
      continue;
    }
    await app.documents(UID).create({
      data: {
        date: event.date,
        title: event.text,
        type: event.kind === 'event' ? 'hari_besar' : 'astronomi',
      },
    });
    created++;
  }
  console.log(`Events: ${created} created, ${skipped} skipped (already present)`);
}

async function main() {
  const { createStrapi, compileStrapi } = require('@strapi/strapi');
  const appContext = await compileStrapi();
  const app = await createStrapi(appContext).load();
  app.log.level = 'error';
  try {
    console.log(
      `Importing ${data.monthStarts.length} month starts and ${data.events.length} events...`,
    );
    await importMonthStarts(app);
    await importEvents(app);
  } finally {
    await app.destroy();
  }
}

main().catch((error) => {
  console.error('Import failed:', error);
  process.exit(1);
});
